import test from 'node:test';import assert from 'node:assert/strict';
import {conversationCast,speakingActor,castPositions} from './dialogue-cast.js';
test('show only illustrated participants in the active conversation',()=>{assert.deepEqual(conversationCast({scene:'dialogue',speaker:'yeogyeong'}),['taei','yeogyeong']);assert.deepEqual(conversationCast({scene:'group',groupParticipants:['seoyeon','soyul','seoyeon']}),['taei','seoyeon','soyul']);assert.deepEqual(conversationCast({scene:'place',speaker:'yeogyeong'}),[]);assert.deepEqual(conversationCast({scene:'dialogue',speaker:'anonymous'}),['taei']);});
test('actual actor tags disambiguate unknown names, narrator and player lines',()=>{const cast=['taei','seoyeon','soyul'];assert.equal(speakingActor({kind:'speech',actor:'soyul',who:'학생'},cast,'seoyeon'),'soyul');assert.equal(speakingActor({kind:'player'},cast,'soyul'),'taei');assert.equal(speakingActor({kind:'narrator'},cast,'soyul'),'');assert.equal(speakingActor({kind:'speech',actor:'yeogyeong'},cast,'soyul'),'');assert.equal(new Set(castPositions(3)).size,3);});
